mapper.update:
UPDATE trade_order
SET status = #{toStatus}
WHERE order_id = #{orderId}
  AND status = #{fromStatus}

UPDATE trade_order
SET status = 2
WHERE order_id = #{orderId}
  AND status = 0
  AND pay_deadline <= #{now}

UPDATE trade_order
SET pay_deadline = #{deadline}
WHERE order_id = #{orderId}

mapper.select:
SELECT *
FROM trade_order
WHERE status = 0
  AND pay_deadline < #{deadline}
ORDER BY pay_deadline ASC
LIMIT #{limit}

SELECT o.*
FROM trade_order o
WHERE o.status = 0
  AND o.pay_deadline >= #{from}
  AND o.pay_deadline < #{to}
  AND (o.next_close_at IS NULL OR o.next_close_at <= #{now})
ORDER BY o.pay_deadline ASC, o.order_id ASC
LIMIT #{limit}

SELECT o.*
FROM trade_order o
WHERE o.status = 0
  AND o.next_close_at IS NOT NULL
  AND o.next_close_at <= #{now}
  AND o.pay_deadline <= #{now}
ORDER BY o.next_close_at ASC, o.order_id ASC
LIMIT #{limit}
